from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode


def apply_rewrite_rules(rules, urls):
    results = []

    for url in urls:
        parsed_url = urlparse(url)
        matched = False
        final_url = url

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            # --- 1. Check Matching ---
            is_match = False

            if match_type == "path_prefix":
                if parsed_url.path.startswith(match_value):
                    is_match = True

            elif match_type == "host":
                host = parsed_url.hostname or ""
                if match_value.startswith("*."):
                    suffix = match_value[2:]
                    # Matches subdomains only, e.g., "a.example.com" matches "*.example.com", but not "example.com"
                    if host.endswith("." + suffix) and host != suffix:
                        is_match = True
                else:
                    if host == match_value:
                        is_match = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    is_match = True

            # --- 2. Apply Action if Matched ---
            if is_match:
                matched = True

                if action == "block":
                    final_url = None
                    break

                elif action == "strip_prefix":
                    path = parsed_url.path
                    if path.startswith(action_value):
                        path = path[len(action_value) :]
                        if not path.startswith("/"):
                            path = "/" + path
                    # Reconstruct URL
                    parsed_url = parsed_url._replace(path=path)
                    final_url = urlunparse(parsed_url)

                elif action == "redirect_host":
                    # action_value is the new host. We need to replace the netloc (host + optional port).
                    old_netloc = parsed_url.netloc
                    if ":" in old_netloc:
                        port = old_netloc.split(":")[1]
                        new_netloc = f"{action_value}:{port}"
                    else:
                        new_netloc = action_value

                    parsed_url = parsed_url._replace(netloc=new_netloc)
                    final_url = urlunparse(parsed_url)

                elif action == "add_query_param":
                    # action_value is typically formatted like "key=value"
                    if "=" in action_value:
                        add_k, add_v = action_value.split("=", 1)
                    else:
                        add_k, add_v = action_value, ""

                    query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                    query_params.append((add_k, add_v))
                    new_query = urlencode(query_params)

                    parsed_url = parsed_url._replace(query=new_query)
                    final_url = urlunparse(parsed_url)

                # Stop checking further rules once the first match is processed
                break

        results.append(final_url)

    return results
